css:
.loader {
  position: relative;
  width: 48px;
  height: 48px;
}
.loader i {
  position: absolute;
  top: 0;
  left: 0;
  width: 10px;
  height: 10px;
  border-radius: 50%;
  background: #6366f1;
  animation: track 2s linear infinite;
}
.loader i:nth-child(1) { animation-delay: 0s; opacity: 1; }
.loader i:nth-child(2) { animation-delay: -0.14s; opacity: 0.82; }
.loader i:nth-child(3) { animation-delay: -0.28s; opacity: 0.64; }
.loader i:nth-child(4) { animation-delay: -0.42s; opacity: 0.46; }
.loader i:nth-child(5) { animation-delay: -0.56s; opacity: 0.3; }
@keyframes track {
  0% { top: 0; left: 0; }
  25% { top: 0; left: calc(100% - 10px); }
  50% { top: calc(100% - 10px); left: calc(100% - 10px); }
  75% { top: calc(100% - 10px); left: 0; }
  100% { top: 0; left: 0; }
}
